package com.bankingax.task.c02;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*; import java.time.Instant;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.mock.web.MockMultipartFile; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.containers.MySQLContainer; import org.testcontainers.junit.jupiter.*;

/** Starts from an empty MySQL database and validates the Flyway V1-V3 schema through JPA. */
@Testcontainers @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"app.c02.document-port=jpa","spring.jpa.hibernate.ddl-auto=validate"})
class JpaDocumentPortMySqlIT {
 @Container static final MySQLContainer<?> MYSQL=new MySQLContainer<>("mysql:8.0.36").withDatabaseName("c02_doc_it").withUsername("test").withPassword("test");
 @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",MYSQL::getJdbcUrl);r.add("spring.datasource.username",MYSQL::getUsername);r.add("spring.datasource.password",MYSQL::getPassword);}
 @Autowired JpaDocumentPort port; @Autowired JdbcTemplate jdbc; @TempDir Path temp;
 @BeforeEach void setup() { jdbc.update("DELETE FROM document_file"); jdbc.update("DELETE FROM required_document"); jdbc.update("DELETE FROM heir"); jdbc.update("DELETE FROM delegation_receipt"); jdbc.update("DELETE FROM service_case"); jdbc.update("DELETE FROM work_item"); jdbc.update("DELETE FROM workflow"); jdbc.update("DELETE FROM document_type"); jdbc.update("DELETE FROM `user`"); seed(); }
 void seed(){jdbc.update("INSERT INTO `user`(id,login_id,password_hash,`role`,name) VALUES(1,'doc-customer','x','CUSTOMER','synthetic')");jdbc.update("INSERT INTO workflow(id,customer_id,status) VALUES(101,1,'RUNNING')");jdbc.update("INSERT INTO work_item(id,workflow_id,task_code,sequence_no,status,request_id) VALUES(8801,101,'INHERITANCE_DEPOSIT',1,'ACTIVE','doc-work')");jdbc.update("INSERT INTO service_case(id,work_item_id,customer_id,case_type,case_status,revision,visit_required,application) VALUES(2001,8801,1,'INHERITANCE_DEPOSIT','DRAFT',0,true,'{}')");jdbc.update("INSERT INTO heir(id,case_id,person_ref,name,relationship,visit_status) VALUES(3001,2001,'h1','synthetic','child','ATTENDING')");jdbc.update("INSERT INTO document_type(code,name,submission_kind) VALUES('HEIR_IDENTITY_CARD','Identity','UPLOAD')");jdbc.update("INSERT INTO required_document(id,work_item_id,document_type_code,heir_id,requirement,status) VALUES(4001,8801,'HEIR_IDENTITY_CARD',3001,'REQUIRED','NOT_SUBMITTED')");}
 @Test void persists_metadata_in_document_file_and_recovers_versions() throws Exception { C02FileStorage storage=new C02FileStorage(temp.toString(),1024); var first=storage.store(new MockMultipartFile("file","first.pdf","application/pdf","%PDF-1.4\nfirst".getBytes())); var one=port.register(reg(first,0)); var two=port.register(reg(storage.store(new MockMultipartFile("file","second.pdf","application/pdf","%PDF-1.4\nsecond".getBytes())),1)); assertEquals(2,two.version()); assertEquals(2,port.findByCase(2001).size()); assertEquals(one.checksum(),port.findById(one.documentFileId()).orElseThrow().checksum()); try(var in=storage.open(one.storageReference())){assertTrue(in.readAllBytes().length>0);} assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM document_file WHERE is_latest=true",Integer.class)); }
 @Test void db_insert_failure_leaves_no_metadata_and_caller_can_compensate_file() throws Exception { C02FileStorage storage=new C02FileStorage(temp.toString(),1024); var stored=storage.store(new MockMultipartFile("file","bad.pdf","application/pdf","%PDF-1.4\nbad".getBytes())); jdbc.execute("ALTER TABLE document_file ADD CONSTRAINT ck_doc_fail CHECK (original_name <> 'bad.pdf')"); try{assertThrows(RuntimeException.class,()->port.register(reg(stored,0))); assertEquals(0,port.findByCase(2001).size());}finally{jdbc.execute("ALTER TABLE document_file DROP CHECK ck_doc_fail"); storage.deleteQuietly(stored.storageKey());} }
 DocumentPort.DocumentRegistration reg(C02FileStorage.StoredFile f,int rev){return new DocumentPort.DocumentRegistration(2001,rev,"HEIR_IDENTITY_CARD:h1",f.originalFilename(),f.contentType(),f.fileSize(),f.storageKey(),C02IntakeService.DocumentStatus.UPLOADED,"HEIR_IDENTITY_CARD",f.checksum(),Instant.now(),1L);}
}
